export const canCancelDispatched=d=>!!d&&!d.readOnly&&!!d.dispatchId&&!d.departedAt&&['queued','received — awaiting status','pending','ready'].includes(d.status);
export const finishedCounterOrder=d=>['delivered','canceled','expired'].includes(d.status);
export function cancelDispatchedOrders(state,shift,packet,command,at){const orders=command.deliveryIds.map(id=>state.deliveries.find(d=>d.id===id)),invalid=orders.some(d=>!d||d.shiftId!==shift.id||d.dispatchPairId!==packet.pairId||!packet.allowedDispatchIds?.includes(d.dispatchId)||!['pending','ready','canceled'].includes(d.status)||d.departedAt||state.runs.some(r=>r.status==='active'&&r.deliveryIds.includes(d.id)));state.dispatchReceipts??=[];state.dispatchReceipts.push(packet.id);state.dispatchCommandResults??={};if(invalid){const message='Order not canceled: it has started, is complete, or belongs to another pairing.';state.dispatchCommandResults[packet.id]={id:packet.id,outcome:'rejected',message,at};return {rejected:message};}let count=0;for(const d of orders)if(d.status!=='canceled'){const previousStatus=d.status;d.status='canceled';d.canceledAt=at;d.cancelSource='dispatch';delete d.scheduleHold;d.events??=[];d.events.push({type:'status-changed',from:previousStatus,to:'canceled',at,source:'dispatch'});count++;}state.dispatchCommandResults[packet.id]={id:packet.id,outcome:'canceled',message:count+' order(s) canceled before departure.',at};return {canceled:count};}
